atts.custom_css:
selector{align-self:flex-start;width:auto;}
selector::before { content:"";position:absolute;top:0px;right:0px;bottom:0px;left:0px;inset:0px;transition:opacity 0.3s;transition-property:opacity;transition-duration:0.3s;transition-timing-function:ease;opacity:0; }
selector:hover { color:var(--text-primary) !important;border-color:oklch(0.75 0.12 180 / 0.4) !important; }
selector:hover::before { opacity:1 !important; }
:where(selector){text-align:center;transition:0.4s cubic-bezier(0.16, 1, 0.3, 1);}

